CREATE TABLE public.rental_organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES public.profiles(user_id), name text NOT NULL CHECK (length(trim(name)) > 0), description text NOT NULL DEFAULT '', location text NOT NULL, website text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.rental_organizations TO authenticated; GRANT SELECT ON public.rental_organizations TO anon; GRANT ALL ON public.rental_organizations TO service_role;
ALTER TABLE public.rental_organizations ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_read ON public.rental_organizations FOR SELECT USING(true);
CREATE POLICY org_write ON public.rental_organizations FOR ALL TO authenticated USING(owner_id=auth.uid() OR public.has_role(auth.uid(),'admin')) WITH CHECK(owner_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.rental_listings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.rental_organizations(id), title text NOT NULL CHECK(length(trim(title))>0), description text NOT NULL, category text NOT NULL CHECK(category IN ('Construction','Tools','Access & lifting','Power & lighting','Transport','Events & production','Other')), location text NOT NULL, image_urls text[] NOT NULL DEFAULT '{}', rate numeric CHECK(rate>=0), currency text NOT NULL DEFAULT 'USD' CHECK(currency IN ('USD','EUR','GBP','RWF')), rate_unit text NOT NULL DEFAULT 'day' CHECK(rate_unit IN ('day','week','month')), minimum_days integer NOT NULL DEFAULT 1 CHECK(minimum_days>0), quantity integer NOT NULL DEFAULT 1 CHECK(quantity>0), available_from date, available_until date, delivery_available boolean NOT NULL DEFAULT false, terms text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'published' CHECK(status IN ('published','paused')), created_at timestamptz NOT NULL DEFAULT now(), CHECK(available_until IS NULL OR available_from IS NULL OR available_until>=available_from));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.rental_listings TO authenticated; GRANT SELECT ON public.rental_listings TO anon; GRANT ALL ON public.rental_listings TO service_role;
ALTER TABLE public.rental_listings ENABLE ROW LEVEL SECURITY;
CREATE POLICY listing_read ON public.rental_listings FOR SELECT USING(status='published' OR EXISTS(SELECT 1 FROM public.rental_organizations o WHERE o.id=organization_id AND o.owner_id=auth.uid()) OR public.has_role(auth.uid(),'admin'));
CREATE POLICY listing_manage ON public.rental_listings FOR ALL TO authenticated USING(EXISTS(SELECT 1 FROM public.rental_organizations o WHERE o.id=organization_id AND o.owner_id=auth.uid()) OR public.has_role(auth.uid(),'admin')) WITH CHECK(EXISTS(SELECT 1 FROM public.rental_organizations o WHERE o.id=organization_id AND o.owner_id=auth.uid()) OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.rental_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), listing_id uuid NOT NULL REFERENCES public.rental_listings(id), requester_id uuid NOT NULL REFERENCES public.profiles(user_id), supplier_id uuid NOT NULL REFERENCES public.profiles(user_id), contact_name text NOT NULL, contact_email text NOT NULL, company text NOT NULL DEFAULT '', start_date date NOT NULL, end_date date NOT NULL, quantity integer NOT NULL DEFAULT 1 CHECK(quantity>0), message text NOT NULL DEFAULT '', status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','declined','cancelled')), created_at timestamptz NOT NULL DEFAULT now(), CHECK(end_date>=start_date), CHECK(requester_id<>supplier_id));
GRANT SELECT,INSERT ON public.rental_requests TO authenticated; GRANT ALL ON public.rental_requests TO service_role;
ALTER TABLE public.rental_requests ENABLE ROW LEVEL SECURITY;
CREATE POLICY request_read ON public.rental_requests FOR SELECT TO authenticated USING(requester_id=auth.uid() OR supplier_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY request_insert ON public.rental_requests FOR INSERT TO authenticated WITH CHECK(requester_id=auth.uid());
CREATE FUNCTION public.validate_rental_request() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l public.rental_listings; owner uuid; BEGIN SELECT * INTO l FROM public.rental_listings WHERE id=NEW.listing_id AND status='published'; IF NOT FOUND THEN RAISE EXCEPTION 'This item is not currently available for requests'; END IF; SELECT owner_id INTO owner FROM public.rental_organizations WHERE id=l.organization_id; NEW.supplier_id:=owner; NEW.status:='pending'; IF NEW.start_date<current_date OR NEW.end_date-NEW.start_date+1<l.minimum_days OR NEW.quantity>l.quantity OR (l.available_from IS NOT NULL AND NEW.start_date<l.available_from) OR (l.available_until IS NOT NULL AND NEW.end_date>l.available_until) THEN RAISE EXCEPTION 'Requested dates or quantity do not match the rental terms'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_rental_request BEFORE INSERT ON public.rental_requests FOR EACH ROW EXECUTE FUNCTION public.validate_rental_request();
CREATE FUNCTION public.respond_rental_request(_id uuid,_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.rental_requests; BEGIN SELECT * INTO r FROM public.rental_requests WHERE id=_id FOR UPDATE; IF NOT FOUND OR auth.uid() IS NULL THEN RAISE EXCEPTION 'Request not found'; END IF; IF r.status<>'pending' THEN RAISE EXCEPTION 'This request has already been resolved'; END IF; IF NOT ((r.supplier_id=auth.uid() AND _status IN ('accepted','declined')) OR (r.requester_id=auth.uid() AND _status='cancelled') OR (public.has_role(auth.uid(),'admin') AND _status IN ('accepted','declined','cancelled'))) THEN RAISE EXCEPTION 'Not permitted'; END IF; UPDATE public.rental_requests SET status=_status WHERE id=_id; END $$;
REVOKE ALL ON FUNCTION public.respond_rental_request(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.respond_rental_request(uuid,text) TO authenticated;
CREATE TABLE public.contact_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(user_id), name text NOT NULL, email text NOT NULL, subject text NOT NULL, message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.contact_submissions TO authenticated; GRANT ALL ON public.contact_submissions TO service_role;
ALTER TABLE public.contact_submissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY contact_insert ON public.contact_submissions FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid());
CREATE POLICY contact_read ON public.contact_submissions FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE INDEX rental_listing_category ON public.rental_listings(status,category,created_at DESC); CREATE INDEX rental_request_parties ON public.rental_requests(requester_id,supplier_id,created_at DESC);
COMMENT ON TABLE public.selling_items IS 'DEPRECATED: sales marketplace retired; commercial rentals use rental_listings. Existing records preserved.';